namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    List<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
            new Department { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
            new Department { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
        ];

        _courses =
        [
            new Course
            {
                Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen",
                InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory CS courses. She earned her Ph.D. from MIT and has published extensively on CS education pedagogy.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new Course
            {
                Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS 201",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes analysis of time and space complexity.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Bob Martinez",
                InstructorBio = "Dr. Martinez specializes in algorithm optimization and competitive programming. He is a two-time ICPC World Finals judge and holds a Ph.D. from Stanford.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new Course
            {
                Id = 3, Title = "Database Systems", CourseCode = "CS 340",
                Description = "Design and implementation of relational database systems. Covers SQL, normalization, transaction processing, query optimization, and an introduction to NoSQL databases.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Carol Wu",
                InstructorBio = "Prof. Wu spent a decade at Oracle before joining academia. Her research focuses on distributed database architectures and query performance.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
            },
            new Course
            {
                Id = 4, Title = "Calculus I", CourseCode = "MATH 151",
                Description = "Introduction to differential calculus. Topics include limits, continuity, derivatives, and applications of differentiation. Emphasis on problem-solving and real-world applications.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park",
                InstructorBio = "Dr. Park is a recipient of the university's Distinguished Teaching Award. He holds a Ph.D. in Applied Mathematics from Caltech.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
            },
            new Course
            {
                Id = 5, Title = "Linear Algebra", CourseCode = "MATH 220",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to systems of equations and geometry.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Roth",
                InstructorBio = "Dr. Roth's research bridges pure mathematics and machine learning. She received her Ph.D. from Princeton and has co-authored two widely used textbooks.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new Course
            {
                Id = 6, Title = "General Physics I", CourseCode = "PHYS 101",
                Description = "Introductory mechanics course covering kinematics, Newton's laws, work and energy, momentum, rotational motion, and simple harmonic motion. Includes weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Frank Nguyen",
                InstructorBio = "Dr. Nguyen is an experimental physicist whose work on particle detectors has been funded by the NSF. He is passionate about hands-on laboratory instruction.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true
            },
            new Course
            {
                Id = 7, Title = "Electromagnetism", CourseCode = "PHYS 230",
                Description = "Electric fields, Gauss's law, electric potential, capacitance, current, magnetic fields, Ampère's law, Faraday's law, and Maxwell's equations. Prerequisites: PHYS 101, MATH 151.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Grace Kim",
                InstructorBio = "Dr. Kim is a theoretical physicist specializing in electromagnetic theory. She previously held a research position at CERN.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false
            },
            new Course
            {
                Id = 8, Title = "Creative Writing", CourseCode = "ENG 210",
                Description = "A workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop original works and participate in peer critique sessions. Open to all majors.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Prof. Hannah Lee",
                InstructorBio = "Prof. Lee is a published novelist and poet. Her debut novel won the National Book Award, and she has been a Guggenheim Fellow.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new Course
            {
                Id = 9, Title = "American Literature", CourseCode = "ENG 310",
                Description = "Survey of American literature from the colonial period through the 21st century. Examines major authors, literary movements, and cultural contexts.",
                Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Ian Brooks",
                InstructorBio = "Dr. Brooks is a scholar of 20th-century American fiction. He earned his Ph.D. from Yale and has published three monographs on American literary modernism.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new Course
            {
                Id = 10, Title = "World History to 1500", CourseCode = "HIST 101",
                Description = "A global survey of human history from the earliest civilizations through the late medieval period. Topics include the rise of empires, trade networks, religious movements, and cultural exchange.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Julia Santos",
                InstructorBio = "Dr. Santos is a historian of the ancient Mediterranean world. She has led archaeological excavations in Greece and Turkey and holds a Ph.D. from Oxford.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = true
            },
            new Course
            {
                Id = 11, Title = "Modern European History", CourseCode = "HIST 260",
                Description = "Europe from the French Revolution to the present. Covers industrialization, nationalism, world wars, the Cold War, and European integration.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Karl Weber",
                InstructorBio = "Dr. Weber specializes in 20th-century European political history. He studied at Humboldt University Berlin before joining the faculty.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database.
        return _courses.Any(c => c.Id == request.CourseId);
    }
}

