                        <h5 class="card-title">@course.Title</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.CourseCode · @course.Credits credits</h6>
                        <p class="card-text"><small class="text-muted">@course.DepartmentName</small></p>
                        <p class="card-text"><small>@course.Schedule</small></p>
                        <p class="card-text"><small>Instructor: @course.InstructorName</small></p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a>
                        <a href="/enroll?courseId=@course.Id" class="btn btn-sm btn-success">Enroll</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Department> departments = [];
    private List<Course> filteredCourses = [];

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (DepartmentId.HasValue)
            _selectedDepartmentId = DepartmentId.Value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        string? search = string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm;
        filteredCourses = CatalogService.GetCourses(search, deptFilter);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        ApplyFilters();
    }
}

